POINT_RULES = (
    ('poll_vote', 5, None),
    ('comment', 5, 5),
    ('song_approved', 20, None),
    ('meme_approved', 20, None),
    ('post_read', 2, 5),
    ('calendar_visit', 2, 1),
)


def seed_rules_and_backfill_rewards(apps, schema_editor):
    rule_model = apps.get_model('blog', 'GamificationPointRule')
    badge_model = apps.get_model('blog', 'Badge')
    user_badge_model = apps.get_model('blog', 'UserBadge')
    user_reward_model = apps.get_model('blog', 'UserDigitalReward')

    for action, points, daily_limit in POINT_RULES:
        rule_model.objects.update_or_create(
            action=action,
            defaults={
                'points': points,
                'daily_limit': daily_limit,
                'active': True,
            },
        )

    for badge in badge_model.objects.all():
        requirement = badge.requirement or {}
        normalized = requirement
        if 'action' in requirement and 'type' not in requirement:
            normalized = {
                'type': 'action_count',
                'action': requirement['action'],
                'target': requirement.get('count', 1),
            }
        elif 'activity_days' in requirement and 'type' not in requirement:
            normalized = {
                'type': 'active_days',
                'target': requirement['activity_days'],
            }
        elif requirement.get('manual_or_event') and 'type' not in requirement:
            normalized = {'type': 'manual'}
        if normalized != requirement:
            badge.requirement = normalized
            badge.save(update_fields=('requirement',))

        reward_ids = list(badge.digital_rewards.filter(active=True).values_list('pk', flat=True))
        if not reward_ids:
            continue
        user_ids = user_badge_model.objects.filter(
            badge_id=badge.pk,
        ).values_list('user_id', flat=True).distinct()
        user_reward_model.objects.bulk_create(
            [
                user_reward_model(
                    user_id=user_id,
                    reward_id=reward_id,
                    source_badge_id=badge.pk,
                )
                for user_id in user_ids
                for reward_id in reward_ids
            ],
            ignore_conflicts=True,
        )


def remove_seeded_rules(apps, schema_editor):
    rule_model = apps.get_model('blog', 'GamificationPointRule')
    rule_model.objects.filter(action__in=[item[0] for item in POINT_RULES]).delete()


